  "inlineSchema": "// Prisma Schema for Namma Tumakuru Parishkara\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  phoneNumber  String   @unique\n  name         String?\n  role         String   @default(\"CITIZEN\") // CITIZEN, OFFICER, ADMIN\n  password     String? // For Officer/Admin login\n  departmentId String?\n  talukId      String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  department     Department?    @relation(fields: [departmentId], references: [id])\n  taluk          Taluk?         @relation(fields: [talukId], references: [id])\n  issues         Issue[]        @relation(\"ReportedIssues\")\n  assignedIssues Issue[]        @relation(\"AssignedOfficerIssues\")\n  upvotes        Upvote[]\n  comments       Comment[]\n  notifications  Notification[]\n}\n\nmodel Department {\n  id          String     @id @default(uuid())\n  code        String     @unique // TCC, PWD, BESCOM, KUWSDB, GRAM_PANCHAYAT, HEALTH, EDUCATION\n  nameEn      String\n  nameKn      String\n  description String?\n  officers    User[]\n  issues      Issue[]\n  categories  Category[]\n}\n\nmodel Taluk {\n  id        String  @id @default(uuid())\n  code      String  @unique\n  nameEn    String\n  nameKn    String\n  latitude  Float\n  longitude Float\n  isUrban   Boolean @default(false)\n  wards     Ward[]\n  issues    Issue[]\n  users     User[]\n}\n\nmodel Ward {\n  id         String  @id @default(uuid())\n  talukId    String\n  wardNumber Int\n  nameEn     String\n  nameKn     String\n  taluk      Taluk   @relation(fields: [talukId], references: [id])\n  issues     Issue[]\n}\n\nmodel Category {\n  id           String     @id @default(uuid())\n  code         String     @unique\n  nameEn       String\n  nameKn       String\n  departmentId String\n  slaHours     Int        @default(48)\n  icon         String     @default(\"alert-circle\")\n  department   Department @relation(fields: [departmentId], references: [id])\n  issues       Issue[]\n}\n\nmodel Issue {\n  id             String @id @default(uuid())\n  trackingNumber String @unique // e.g. \"TUM-2026-0001\"\n  title          String\n  description    String\n  status         String @default(\"SUBMITTED\") // SUBMITTED, VERIFIED, ASSIGNED, IN_PROGRESS, RESOLVED, CLOSED, REOPENED\n  urgency        String @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, EMERGENCY\n\n  // Geolocation\n  latitude    Float\n  longitude   Float\n  addressText String?\n  talukId     String\n  wardId      String?\n\n  // Relations\n  categoryId   String\n  departmentId String\n  reporterId   String\n  assignedToId String?\n\n  // Media\n  photoUrls        String // JSON serialized array of string paths: '[\"/uploads/img1.jpg\"]'\n  resolutionPhotos String? // JSON serialized array of resolution proof paths\n  resolutionNotes  String?\n\n  // SLA and Timestamps\n  slaDeadline DateTime\n  resolvedAt  DateTime?\n  closedAt    DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  taluk           Taluk      @relation(fields: [talukId], references: [id])\n  ward            Ward?      @relation(fields: [wardId], references: [id])\n  category        Category   @relation(fields: [categoryId], references: [id])\n  department      Department @relation(fields: [departmentId], references: [id])\n  reporter        User       @relation(\"ReportedIssues\", fields: [reporterId], references: [id])\n  assignedOfficer User?      @relation(\"AssignedOfficerIssues\", fields: [assignedToId], references: [id])\n\n  timeline      IssueTimeline[]\n  upvotes       Upvote[]\n  comments      Comment[]\n  notifications Notification[]\n}\n\nmodel IssueTimeline {\n  id        String   @id @default(uuid())\n  issueId   String\n  status    String\n  actionEn  String\n  actionKn  String\n  notes     String?\n  actorName String?\n  actorRole String   @default(\"CITIZEN\")\n  createdAt DateTime @default(now())\n\n  issue Issue @relation(fields: [issueId], references: [id], onDelete: Cascade)\n}\n\nmodel Upvote {\n  id        String   @id @default(uuid())\n  issueId   String\n  userId    String\n  createdAt DateTime @default(now())\n\n  issue Issue @relation(fields: [issueId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([issueId, userId])\n}\n\nmodel Comment {\n  id        String   @id @default(uuid())\n  issueId   String\n  userId    String\n  text      String\n  isOfficer Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  issue Issue @relation(fields: [issueId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  issueId   String?\n  titleEn   String\n  titleKn   String\n  messageEn String\n  messageKn String\n  isRead    Boolean  @default(false)\n  channel   String   @default(\"IN_APP\") // IN_APP, SMS_MOCK, WHATSAPP_MOCK\n  createdAt DateTime @default(now())\n\n  user  User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  issue Issue? @relation(fields: [issueId], references: [id], onDelete: SetNull)\n}\n",
